package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraftforge.eventbus.api.*;import net.minecraftforge.event.level.*;import net.minecraft.core.*;import net.minecraft.server.level.*;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid=SbwDroneRangeConfig.MOD_ID)
public final class Pb01Events{
 public static final ThreadLocal<Boolean>CHECKING=ThreadLocal.withInitial(()->false);
 public static boolean permitBreak(ServerPlayer p,BlockPos at){if(!p.serverLevel().hasChunkAt(at)||!p.serverLevel().mayInteract(p,at))return false;boolean old=CHECKING.get();CHECKING.set(true);try{return !net.minecraftforge.common.MinecraftForge.EVENT_BUS.post(new BlockEvent.BreakEvent(p.serverLevel(),at,p.serverLevel().getBlockState(at),p));}finally{CHECKING.set(old);}}
 public static boolean mayRemove(ServerPlayer p,Pb01BlockEntity b){if(!b.allowed(p,true))return false;for(var at:Pb01Geometry.MODEL.all(b.getBlockPos(),b.facing()))if(!permitBreak(p,at))return false;return true;}
 @SubscribeEvent(priority=EventPriority.HIGHEST)public static void breaking(BlockEvent.BreakEvent e){if(CHECKING.get()||!(e.getLevel()instanceof ServerLevel l)||!(e.getPlayer()instanceof ServerPlayer p))return;var s=e.getState();if(s.getBlock()instanceof Pb01Block){var b=Pb01Block.main(l,e.getPos(),s);if(b==null||!b.allowed(p,true)||!mayRemove(p,b))e.setCanceled(true);}else if(l.getBlockEntity(e.getPos())instanceof Dvt01BlockEntity d&&d.pbRoot!=null){var b=Pb01Dvt.bunker(d);if(b==null||!b.allowed(p,true))e.setCanceled(true);}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void use(net.minecraftforge.event.entity.player.PlayerInteractEvent.RightClickBlock e){var s=e.getLevel().getBlockState(e.getPos());if(e.getEntity().isShiftKeyDown()&&e.getItemStack().is(com.atsuishio.superbwarfare.init.ModTags.Items.TOOLS_CROWBAR)){if(s.getBlock()instanceof Pb01Block b){e.setCanceled(true);e.setCancellationResult(e.getLevel().isClientSide?net.minecraft.world.InteractionResult.SUCCESS:b.interact(s,e.getLevel(),e.getPos(),e.getEntity(),e.getHand(),e.getHitVec()));}else if(e.getLevel().getBlockEntity(e.getPos())instanceof Dvt01BlockEntity d&&d.pbRoot!=null){e.setCanceled(true);if(e.getEntity()instanceof ServerPlayer p){var b=Pb01Dvt.bunker(d);if(b!=null)Pb01Dvt.detach(b,p,true);}e.setCancellationResult(net.minecraft.world.InteractionResult.SUCCESS);}}}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void creative(net.minecraftforge.event.entity.player.PlayerInteractEvent.LeftClickBlock e){if(!(e.getEntity()instanceof ServerPlayer p)||!p.isCreative()||!(e.getLevel().getBlockState(e.getPos()).getBlock()instanceof Pb01Block))return;var b=Pb01Block.main(e.getLevel(),e.getPos(),e.getLevel().getBlockState(e.getPos()));if(b!=null&&b.allowed(p,true)&&mayRemove(p,b)){e.setCanceled(true);b.remove(p,false,false);}}
 @SubscribeEvent public static void loaded(ChunkEvent.Load e){if(e.getLevel()instanceof ServerLevel l){long key=e.getChunk().getPos().toLong();l.getServer().tell(new net.minecraft.server.TickTask(l.getServer().getTickCount()+1,()->Pb01WorldData.get(l).chunk(l,key)));}}
 @SubscribeEvent(priority=EventPriority.LOWEST,receiveCanceled=true)public static void denied(BlockEvent.EntityPlaceEvent e){if(e.isCanceled()&&e.getEntity()instanceof ServerPlayer p&&(e.getPlacedBlock().getBlock()instanceof Pb01Block||e.getPlacedBlock().getBlock()instanceof Dvt01Block&&e.getLevel().getBlockEntity(e.getPos())instanceof Dvt01BlockEntity mounted&&mounted.pbRoot!=null))p.displayClientMessage(net.minecraft.network.chat.Component.translatable("pb01.claim_denied"),true);}
}
